(async () => {
  const rows = await FileAttachment("sales.csv").csv({typed: true});
  const by = d3.rollups(rows.filter(r => new Date(r.date).getFullYear() === 2025), v => d3.sum(v, d => d.revenue), r => new Date(r.date).getMonth());
  const data = by.sort((a, b) => a[0] - b[0]).map(([m, revenue]) => ({month: new Date(2025, m, 1), revenue}));
  return Plot.plot({
    width: 800, height: 420, marginLeft: 60,
    title: "Monthly revenue, 2025",
    x: {type: "band", tickFormat: d => d3.timeFormat("%b")(d), label: null},
    y: {label: "Revenue ($)", grid: true, tickFormat: "s"},
    marks: [
      Plot.barY(data, {x: "month", y: "revenue", fill: "#3b6fd4"}),
      Plot.text(data, {x: "month", y: "revenue", text: d => d3.format(",")(d.revenue), dy: -8, fontSize: 11}),
      Plot.ruleY([0])
    ]
  });
})()

{
  const data = [{ task: "meetings", value: 30 }, { task: "coding", value: 50 }, { task: "review", value: 20 }];
  const w = 360, r = 150;
  const color = d3.scaleOrdinal(data.map(d => d.task), d3.schemeTableau10);
  const arcs = d3.pie().sort(null).value(d => d.value)(data);
  const arc = d3.arc().innerRadius(0).outerRadius(r);
  const label = d3.arc().innerRadius(r * 0.65).outerRadius(r * 0.65);
  const svg = d3.create("svg").attr("viewBox", [-w / 2, -w / 2, w, w]).attr("width", w).attr("height", w);
  const g = svg.selectAll("g").data(arcs).join("g");
  g.append("path").attr("d", arc).attr("fill", d => color(d.data.task)).attr("stroke", "white");
  g.append("text").attr("transform", d => `translate(${label.centroid(d)})`).attr("text-anchor", "middle")
    .attr("fill", "white").attr("font-size", 13)
    .text(d => `${d.data.task} ${d.data.value}%`);
  return svg.node();
}

